$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
. (Join-Path $root 'validation/custom-app-production-pre-apply-preparation-v0.1.0/test_custom_app_production_pre_apply_preparation.ps1')
. (Join-Path $root 'validation/custom-app-production-crash-recovery-journal-v0.1.0/custom-app-production-crash-recovery-journal.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-recovery-evidence.ps1')

function Assert-RETrue([bool]$v,[string]$m){if(-not$v){throw$m}}
function Assert-REFalse([bool]$v,[string]$m){if($v){throw$m}}
function Assert-REEq($a,$b,[string]$m){if([string]$a-cne[string]$b){throw"$m actual=<$a> expected=<$b>"}}
function Copy-RE($x){return(($x|ConvertTo-Json -Depth 40)|ConvertFrom-Json)}

function New-RecoveryEvidenceFixtureV010 {
    param([string]$Label,[string]$Name='tagify',[string]$Source='alexk218/tagify',[string]$Manifest='Tagify',[string]$Nonce='12121212121212121212121212121212',[AllowNull()]$PreparedOverride=$null)
    $q=New-PreApplyFixtureV010 -Label ('recovery-evidence-'+$Label) -Name $Name -Source $Source -Manifest $Manifest -Nonce $Nonce
    $prep=Invoke-PreApplyFixtureV010 -Q $q
    if(-not[bool]$prep.ok){throw('evidence fixture pre-apply failed: '+[string]$prep.reason)}
    $prepared=$(if($null-ne$PreparedOverride){$PreparedOverride}else{$prep.result})
    $allowed=[IO.Path]::GetFullPath($env:RUNNER_TEMP).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)
    $txn=Join-Path $q.x.base ('.spotify-control-txn-'+[Guid]::NewGuid().ToString('N'))
    $store=Join-Path $q.x.base 'recovery-journal'
    $id=New-CustomAppProductionCrashJournalIdentityV010 -Name ([string]$prepared.name) -ConsumptionId ([string]$prepared.consumption_id) -SourceIdentity ([string]$prepared.source_identity) -RemoteCommitSha ([string]$prepared.remote_commit_sha) -StageResultFingerprint ([string]$prepared.stage_result_fingerprint) -PreparationFingerprint ([string]$prepared.preparation_fingerprint) -AllowedRoot $allowed -LivePath $q.x.live -TransactionRoot $txn -StageWorkspacePath ([string]$prepared.stage_workspace_path) -AppBackupPath ([string]$prepared.app_backup_path) -PersistenceBackupPath ([string]$prepared.persistence_backup_path)
    $init=Initialize-CustomAppProductionCrashJournalV010 -AllowedRoot $allowed -StoreDirectory $store -Identity $id -Now ([DateTimeOffset]::UtcNow.AddMinutes(-1))
    if(-not[bool]$init.ok){throw('evidence fixture journal init failed: '+[string]$init.reason)}
    return[pscustomobject]@{q=$q;prep=$prep;prepared=$prepared;allowed=$allowed;txn=$txn;store=$store;identity=$id;init=$init}
}
function Write-REFixtureV010($f){return Write-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $f.allowed -StoreDirectory $f.store -PreparedResult $f.prepared -Now ([DateTimeOffset]::UtcNow.AddMinutes(-1).AddSeconds(1))}
function Read-REFixtureV010($f,[string]$Tx=$null){if([string]::IsNullOrWhiteSpace($Tx)){$Tx=[string]$f.identity.transaction_id};return Read-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $f.allowed -StoreDirectory $f.store -ExpectedTransactionId $Tx}
function Assert-RENoAuthority($r,[string]$label){foreach($p in @('evidence_is_authority','execution_authorized','restore_authorized','apply_authorized','cleanup_authorized','production_mutation_authorized')){Assert-REFalse ([bool]$r.$p) "$label authority escaped $p"}}

$count=0
$valid=New-RecoveryEvidenceFixtureV010 'valid';$w=Write-REFixtureV010 $valid;Assert-RETrue ([bool]$w.ok) ('valid write denied: '+[string]$w.reason);Assert-RETrue ([bool]$w.persisted) 'valid evidence not persisted';Assert-RETrue ([bool]$w.read_after_write_verified) 'valid evidence no readback';Assert-RENoAuthority $w 'valid-write';$r=Read-REFixtureV010 $valid;Assert-RETrue ([bool]$r.ok) ('valid read denied: '+[string]$r.reason);Assert-RETrue ([bool]$r.reloaded_from_persistent_store) 'valid evidence not reloaded';Assert-REEq $r.transaction_id $valid.identity.transaction_id 'valid transaction';Assert-REEq $r.preparation_fingerprint $valid.prepared.preparation_fingerprint 'valid prep fingerprint';Assert-RENoAuthority $r 'valid-read';$count++

$future=New-RecoveryEvidenceFixtureV010 'future' -Name 'future-app' -Source 'owner/future-app' -Manifest 'Future App' -Nonce ('3'*32);$fw=Write-REFixtureV010 $future;Assert-RETrue ([bool]$fw.ok) ('future evidence write denied: '+[string]$fw.reason);$fr=Read-REFixtureV010 $future;Assert-RETrue ([bool]$fr.ok) 'future evidence read denied';Assert-REEq $fr.envelope.name 'future-app' 'future name';$count++

$replay=Write-REFixtureV010 $valid;Assert-REFalse ([bool]$replay.ok) 'evidence replay accepted';Assert-REEq $replay.reason 'recovery-evidence-already-exists-replay-denied' 'replay reason';$count++

$advanced=New-RecoveryEvidenceFixtureV010 'advanced' -Nonce ('4'*32);$a=Append-CustomAppProductionCrashJournalPhaseV010 -AllowedRoot $advanced.allowed -StoreDirectory $advanced.store -ExpectedRevision ([int64]$advanced.init.revision) -ExpectedEntrySha256 ([string]$advanced.init.entry.entry_sha256) -Phase 'atomic-mutation-starting' -Now ([DateTimeOffset]::UtcNow.AddMinutes(-1).AddSeconds(2));Assert-RETrue ([bool]$a.ok) 'advance failed';$aw=Write-REFixtureV010 $advanced;Assert-REFalse ([bool]$aw.ok) 'late evidence creation accepted';Assert-REEq $aw.reason 'recovery-evidence-must-be-created-at-prepared-revision-zero' 'late write reason';$count++

$advRead=New-RecoveryEvidenceFixtureV010 'advanced-read' -Nonce ('5'*32);$arw=Write-REFixtureV010 $advRead;Assert-RETrue ([bool]$arw.ok) 'advanced-read initial evidence write failed';$arj=Read-CustomAppProductionCrashJournalV010 -AllowedRoot $advRead.allowed -StoreDirectory $advRead.store;$ara=Append-CustomAppProductionCrashJournalPhaseV010 -AllowedRoot $advRead.allowed -StoreDirectory $advRead.store -ExpectedRevision ([int64]$arj.revision) -ExpectedEntrySha256 ([string]$arj.entry.entry_sha256) -Phase 'atomic-mutation-starting' -Now ([DateTimeOffset]::UtcNow.AddMinutes(-1).AddSeconds(3));Assert-RETrue ([bool]$ara.ok) 'advanced-read phase append failed';$arr=Read-REFixtureV010 $advRead;Assert-RETrue ([bool]$arr.ok) ('evidence failed after phase advance: '+[string]$arr.reason);Assert-REEq $arr.journal_phase 'atomic-mutation-starting' 'advanced read journal phase';$count++

$tamper=New-RecoveryEvidenceFixtureV010 'prepared-tamper' -Nonce ('6'*32);$bad=Copy-RE $tamper.prepared;$bad.app_backup_tree_sha256=('0'*64);$bad.preparation_fingerprint=Get-CustomAppProductionPreApplySha256V010 -Text (Get-CustomAppProductionPreApplyResultMaterialV010 -Result $bad);$tw=Write-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $tamper.allowed -StoreDirectory $tamper.store -PreparedResult $bad;Assert-REFalse ([bool]$tw.ok) 'prepared rehash tamper accepted against journal anchor';Assert-RETrue ([string]$tw.reason -like '*prepared-journal-mismatch-preparation_fingerprint*') ('prepared rehash reason drifted: '+[string]$tw.reason);$count++

$authorityQ=New-PreApplyFixtureV010 -Label 'recovery-evidence-authority' -Nonce ('7'*32);$authorityPrep=Invoke-PreApplyFixtureV010 -Q $authorityQ;if(-not[bool]$authorityPrep.ok){throw'authority fixture preapply failed'};$badAuth=Copy-RE $authorityPrep.result;$badAuth.apply_authorized=$true;$badAuth.preparation_fingerprint=Get-CustomAppProductionPreApplySha256V010 -Text (Get-CustomAppProductionPreApplyResultMaterialV010 -Result $badAuth)
$allowed=[IO.Path]::GetFullPath($env:RUNNER_TEMP).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$txn=Join-Path $authorityQ.x.base ('.spotify-control-txn-'+[Guid]::NewGuid().ToString('N'));$store=Join-Path $authorityQ.x.base 'authority-journal';$id=New-CustomAppProductionCrashJournalIdentityV010 -Name $badAuth.name -ConsumptionId $badAuth.consumption_id -SourceIdentity $badAuth.source_identity -RemoteCommitSha $badAuth.remote_commit_sha -StageResultFingerprint $badAuth.stage_result_fingerprint -PreparationFingerprint $badAuth.preparation_fingerprint -AllowedRoot $allowed -LivePath $authorityQ.x.live -TransactionRoot $txn -StageWorkspacePath $badAuth.stage_workspace_path -AppBackupPath $badAuth.app_backup_path -PersistenceBackupPath $badAuth.persistence_backup_path;$init=Initialize-CustomAppProductionCrashJournalV010 -AllowedRoot $allowed -StoreDirectory $store -Identity $id -Now ([DateTimeOffset]::UtcNow.AddMinutes(-1));Assert-RETrue ([bool]$init.ok) 'authority journal init failed';$authw=Write-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $allowed -StoreDirectory $store -PreparedResult $badAuth;Assert-REFalse ([bool]$authw.ok) 'authority-polluted prepared result accepted';Assert-RETrue ([string]$authw.reason -like '*prepared-result-authority-escaped-apply_authorized*') ('authority reason drifted: '+[string]$authw.reason);$count++

$pathMismatch=New-RecoveryEvidenceFixtureV010 'path-mismatch' -Nonce ('8'*32);$badPath=Copy-RE $pathMismatch.prepared;$badPath.stage_workspace_path=Join-Path $pathMismatch.q.x.base 'different-workspace';$badPath.preparation_fingerprint=Get-CustomAppProductionPreApplySha256V010 -Text (Get-CustomAppProductionPreApplyResultMaterialV010 -Result $badPath);$pw=Write-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $pathMismatch.allowed -StoreDirectory $pathMismatch.store -PreparedResult $badPath;Assert-REFalse ([bool]$pw.ok) 'prepared path mismatch accepted';$count++

$fileTamper=New-RecoveryEvidenceFixtureV010 'file-tamper' -Nonce ('9'*32);$ftw=Write-REFixtureV010 $fileTamper;Assert-RETrue ([bool]$ftw.ok) 'file tamper setup failed';$obj=[IO.File]::ReadAllText([string]$ftw.path,[Text.UTF8Encoding]::new($false))|ConvertFrom-Json;$obj.app_backup_tree_sha256=('f'*64);$obj.evidence_fingerprint=Get-CustomAppProductionRecoveryEvidenceSha256V010 (Get-CustomAppProductionRecoveryEvidenceMaterialV010 $obj);[IO.File]::WriteAllText([string]$ftw.path,($obj|ConvertTo-Json -Depth 40 -Compress),[Text.UTF8Encoding]::new($false));$ftr=Read-REFixtureV010 $fileTamper;Assert-REFalse ([bool]$ftr.ok) 'top-level evidence tamper + rehash accepted';Assert-RETrue ([string]$ftr.reason -like '*prepared-mismatch-app_backup_tree_sha256*') ('top-level tamper reason drifted: '+[string]$ftr.reason);$count++

$deep=New-RecoveryEvidenceFixtureV010 'deep-tamper' -Nonce ('a'*32);$dw=Write-REFixtureV010 $deep;Assert-RETrue ([bool]$dw.ok) 'deep tamper setup failed';$o=[IO.File]::ReadAllText([string]$dw.path,[Text.UTF8Encoding]::new($false))|ConvertFrom-Json;$o.prepared_result.app_backup_tree_sha256=('e'*64);$o.prepared_result.preparation_fingerprint=Get-CustomAppProductionPreApplySha256V010 -Text (Get-CustomAppProductionPreApplyResultMaterialV010 -Result $o.prepared_result);$o.app_backup_tree_sha256=('e'*64);$o.preparation_fingerprint=[string]$o.prepared_result.preparation_fingerprint;$o.prepared_result_material_sha256=[string]$o.prepared_result.preparation_fingerprint;$o.evidence_fingerprint=Get-CustomAppProductionRecoveryEvidenceSha256V010 (Get-CustomAppProductionRecoveryEvidenceMaterialV010 $o);[IO.File]::WriteAllText([string]$dw.path,($o|ConvertTo-Json -Depth 40 -Compress),[Text.UTF8Encoding]::new($false));$dr=Read-REFixtureV010 $deep;Assert-REFalse ([bool]$dr.ok) 'deep prepared+envelope tamper + rehash accepted';Assert-RETrue ([string]$dr.reason -like '*prepared-journal-mismatch-preparation_fingerprint*') ('deep tamper reason drifted: '+[string]$dr.reason);$count++

$corrupt=New-RecoveryEvidenceFixtureV010 'corrupt' -Nonce ('b'*32);$cw=Write-REFixtureV010 $corrupt;Assert-RETrue ([bool]$cw.ok) 'corrupt setup failed';[IO.File]::WriteAllText([string]$cw.path,'{not-json',[Text.UTF8Encoding]::new($false));$cr=Read-REFixtureV010 $corrupt;Assert-REFalse ([bool]$cr.ok) 'corrupt evidence JSON accepted';Assert-REEq $cr.reason 'recovery-evidence-JSON-invalid' 'corrupt evidence reason';$count++

$wrong=New-RecoveryEvidenceFixtureV010 'wrong-tx' -Nonce ('c'*32);$ww=Write-REFixtureV010 $wrong;Assert-RETrue ([bool]$ww.ok) 'wrong tx setup failed';$wr=Read-REFixtureV010 $wrong ('d'*64);Assert-REFalse ([bool]$wr.ok) 'wrong transaction accepted';Assert-REEq $wr.reason 'recovery-evidence-transaction-mismatch' 'wrong transaction reason';$count++

$journalCorrupt=New-RecoveryEvidenceFixtureV010 'journal-corrupt' -Nonce ('d'*32);$jcw=Write-REFixtureV010 $journalCorrupt;Assert-RETrue ([bool]$jcw.ok) 'journal corrupt setup failed';[IO.File]::WriteAllText((Join-Path $journalCorrupt.store 'current.json'),'{bad',[Text.UTF8Encoding]::new($false));$jcr=Read-REFixtureV010 $journalCorrupt;Assert-REFalse ([bool]$jcr.ok) 'corrupt journal accepted by evidence read';Assert-RETrue ([string]$jcr.reason -like 'recovery-evidence-journal-read-denied:*') 'corrupt journal reason drifted';$count++

$lock=New-RecoveryEvidenceFixtureV010 'lock' -Nonce ('e'*32);$lw=Write-REFixtureV010 $lock;Assert-RETrue ([bool]$lw.ok) 'lock setup failed';$jp=Get-CustomAppProductionCrashJournalPathsV010 -AllowedRoot $lock.allowed -StoreDirectory $lock.store;$held=[IO.File]::Open([string]$jp.lock,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{$lr=Read-REFixtureV010 $lock}finally{$held.Dispose()};Assert-REFalse ([bool]$lr.ok) 'lock contention accepted';Assert-REEq $lr.reason 'crash-journal-lock-busy' 'lock reason';$count++

$oversize=New-RecoveryEvidenceFixtureV010 'oversize' -Nonce ('f'*32);$ow=Write-REFixtureV010 $oversize;Assert-RETrue ([bool]$ow.ok) 'oversize setup failed';$blob='x'*(4194305);[IO.File]::WriteAllText([string]$ow.path,$blob,[Text.UTF8Encoding]::new($false));$or=Read-REFixtureV010 $oversize;Assert-REFalse ([bool]$or.ok) 'oversize evidence accepted';Assert-REEq $or.reason 'recovery-evidence-file-exceeds-4-MiB' 'oversize reason';$count++

$probeFixture=New-RecoveryEvidenceFixtureV010 'probe' -Nonce ('1'*32);$probeWrite=Write-REFixtureV010 $probeFixture;Assert-RETrue ([bool]$probeWrite.ok) 'probe setup failed';$probe=Join-Path $PSScriptRoot 'probe_custom_app_production_recovery_evidence.ps1';$raw=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $probe -AllowedRoot $probeFixture.allowed -StoreDirectory $probeFixture.store -ExpectedTransactionId ([string]$probeFixture.identity.transaction_id);if($LASTEXITCODE){throw'separate-process recovery evidence probe failed'};$pj=($raw|Select-Object -Last 1)|ConvertFrom-Json;Assert-RETrue ([bool]$pj.ok) ('probe read failed: '+[string]$pj.reason);Assert-REEq $pj.transaction_id $probeFixture.identity.transaction_id 'probe transaction';Assert-REFalse ([bool]$pj.production_mutation_authorized) 'probe authority escaped';$count++

Write-Host "CUSTOM_APP_PRODUCTION_RECOVERY_EVIDENCE_MATRIX_PASS total=$count"
